package com.chance.bitlifediag;
import android.app.*;import android.content.*;import android.graphics.Bitmap;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;
/** A user-triggered capture of this game's Unity surface, plus a bug note. */
public final class DiagnosticsSnapshot54 {
 private static SurfaceView surface(View view){if(view instanceof SurfaceView)return(SurfaceView)view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){SurfaceView found=surface(group.getChildAt(i));if(found!=null)return found;}}return null;}
 public static void capture(final Activity a){final EditText note=new EditText(a);note.setHint("What did you tap? What happened?");new AlertDialog.Builder(a).setTitle("Capture this bug").setView(note).setPositiveButton("Capture",new DialogInterface.OnClickListener(){public void onClick(DialogInterface dialog,int which){final File root=RuntimeLogCapture.diagnosticRoot();if(root==null)return;try{String details="Time: "+System.currentTimeMillis()+"\nBuild: v54\nNote: "+note.getText()+"\nMemory: "+Runtime.getRuntime().totalMemory()+" total / "+Runtime.getRuntime().freeMemory()+" free\nDisplay: "+a.getResources().getDisplayMetrics()+"\nRecorder: "+RuntimeLogCapture.status();CrashJournal.save(new File(root,"bug-snapshot.txt"),details);RuntimeLogCapture.mark("Bug snapshot: "+note.getText());}catch(IOException error){RuntimeLogCapture.failure("Saving bug note",error);}
 final SurfaceView game=surface(a.getWindow().getDecorView());if(game==null||game.getWidth()<1||game.getHeight()<1){Toast.makeText(a,"Bug note saved. Open the game to capture its screen.",1).show();return;}
 final float factor=Math.min(1f,1280f/Math.max(game.getWidth(),game.getHeight()));final Bitmap bitmap=Bitmap.createBitmap(Math.max(1,Math.round(game.getWidth()*factor)),Math.max(1,Math.round(game.getHeight()*factor)),Bitmap.Config.ARGB_8888);
 try{PixelCopy.request(game,bitmap,new PixelCopy.OnPixelCopyFinishedListener(){public void onPixelCopyFinished(int result){try{if(result==PixelCopy.SUCCESS){try(FileOutputStream out=new FileOutputStream(new File(root,"game-screenshot.png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);out.getFD().sync();}RuntimeLogCapture.mark("Game screenshot saved");Toast.makeText(a,"Screenshot and note saved. Use Save full diagnostic ZIP.",1).show();}else RuntimeLogCapture.mark("Screenshot result: "+result);}catch(IOException error){RuntimeLogCapture.failure("Saving screenshot",error);}finally{bitmap.recycle();}}},new Handler(Looper.getMainLooper()));}catch(RuntimeException error){bitmap.recycle();RuntimeLogCapture.failure("Capturing Unity surface",error);}
 }}).setNegativeButton("Cancel",null).show();}
 private DiagnosticsSnapshot54(){}
}
